(function(){
const labels={
 fireDailyHelp:['按月份逐日填寫；Ｏ符合規定、Ｖ立即改善後符合規定、Ｘ不符合規定且無法立即改善。發現異常時，應立即報告防火管理人。','Complete the monthly record by day. O meets requirements, V meets requirements after immediate correction, and X is non-compliant and cannot be corrected immediately. Report abnormalities to the fire safety manager at once.','Complete el registro mensual por día. O cumple, V cumple tras corregir de inmediato y X no cumple y no puede corregirse de inmediato. Informe de inmediato las anomalías al responsable de seguridad contra incendios.','Điền theo ngày trong tháng. O phù hợp, V phù hợp sau khi khắc phục ngay, X không phù hợp và không thể khắc phục ngay. Báo ngay bất thường cho người quản lý PCCC.'],
 fireMonth:['檢查年月','Inspection month','Mes de inspección','Tháng kiểm tra'],fireArea:['負責區域','Responsible area','Área responsable','Khu vực phụ trách'],fireImplementer:['實施人員','Inspector','Responsable','Nhân viên thực hiện'],fireDay:['日期','Day','Día','Ngày'],fireUse:['用火設備使用情形','Use of fire equipment','Uso de equipos con fuego','Tình trạng sử dụng thiết bị dùng lửa'],fireWiring:['電器設備配線','Electrical wiring','Cableado eléctrico','Dây dẫn điện'],fireCigarette:['煙蒂處理','Cigarette butt disposal','Manejo de colillas','Xử lý đầu lọc thuốc lá'],fireShutdown:['下班時火源管理','Fire source control at end of shift','Control al terminar el turno','Quản lý nguồn lửa khi tan ca'],fireCombustibles:['共用設備可燃物管理','Combustibles near shared equipment','Materiales combustibles en equipos compartidos','Quản lý vật liệu dễ cháy tại thiết bị dùng chung'],fireNote:['附記','Notes','Notas','Ghi chú'],
 fireNew:['新增本月表單','New monthly form','Nuevo formulario mensual','Tạo biểu mẫu tháng mới'],fireOpen:['檢視','View','Ver','Xem'],fireModify:['修改草稿','Edit draft','Editar borrador','Sửa bản nháp'],fireReview:['主管處置','Manager review','Revisión del supervisor','Quản lý xử lý'],fireSaveDraft:['儲存草稿','Save draft','Guardar borrador','Lưu bản nháp'],fireSubmit:['送交防火管理人','Submit to fire safety manager','Enviar al responsable PCCC','Gửi người quản lý PCCC'],fireDraft:['草稿','Draft','Borrador','Bản nháp'],fireSubmitted:['待防火管理人處置','Awaiting fire safety manager','Pendiente del responsable PCCC','Chờ người quản lý PCCC'],fireConfirmed:['已簽章完成','Reviewed and signed','Revisado y firmado','Đã kiểm tra và ký'],fireManagerTitle:['防火管理人處置情形暨簽章','Fire safety manager action and signature','Acción y firma del responsable PCCC','Tình hình xử lý và ký xác nhận của người quản lý PCCC'],fireManagerName:['防火管理人姓名','Fire safety manager','Responsable PCCC','Người quản lý PCCC'],fireDisposition:['處置情形','Action taken','Medida aplicada','Tình trạng xử lý'],fireSignature:['簽章／簽名','Signature','Firma','Ký tên'],fireComplete:['確認完成並簽章','Confirm and sign','Confirmar y firmar','Xác nhận và ký'],fireReturn:['退回補正','Return for correction','Devolver para corregir','Trả lại để bổ sung'],fireRequired:['請填寫實施人員與負責區域。','Enter the inspector and responsible area.','Indique el responsable y el área.','Vui lòng nhập người thực hiện và khu vực phụ trách.'],fireAllDays:['送出前請完成本月截至今日的每日檢查項目。','Complete every daily item through today before submitting.','Complete los puntos diarios hasta hoy antes de enviar.','Hãy hoàn thành các mục kiểm tra hằng ngày đến hôm nay trước khi gửi.'],fireReviewRequired:['請填寫防火管理人姓名、處置情形及簽章。','Enter the manager name, action taken, and signature.','Indique el nombre, la medida y la firma del responsable.','Vui lòng nhập tên, tình trạng xử lý và chữ ký của người quản lý PCCC.'],fireAbnormal:['如有異常現象，應立即報告防火管理人。','Report abnormalities to the fire safety manager immediately.','Informe de inmediato las anomalías al responsable PCCC.','Nếu có bất thường, phải báo ngay cho người quản lý PCCC.']
};
const tr=k=>{const row=labels[k];return row?row[{zh:0,en:1,es:2,vi:3}[primary]??0]:txt(k);};
let records=[],departments=[],current=null,listMonth='',listDepartment='',historyOrigin=false;
const monthNow=()=>{const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit'}).format(new Date());return p;};
const monthDays=m=>new Date(Number(m.slice(0,4)),Number(m.slice(5,7)),0).getDate();
const localDept=d=>d?multilingual({zh:d.name_zh,en:d.name_en||d.name_zh,es:d.name_es||d.name_zh,vi:d.name_vi||d.name_zh}):'';
const statusText=s=>tr(s==='confirmed'?'fireConfirmed':s==='submitted'?'fireSubmitted':'fireDraft');
const statusLabel=s=>`<span class="tag ${s==='confirmed'?'normal':s==='submitted'?'pending':'none'} fire-status">${esc(statusText(s))}</span>`;
async function fetchList(){const result=await api({action:'fire_daily_list'});records=result.records||[];departments=result.departments||[];}
function fresh(month=monthNow(),dept=departments.find(d=>d.id===profile?.department_id)?.id||departments[0]?.id||'') {return {id:crypto.randomUUID(),department_id:dept,inspection_month:month,responsible_area:'',implementer_name:localStorage.getItem('inspection_operator_name')||'',entries:Array.from({length:monthDays(month)},(_,i)=>({day:i+1,fire_use:'',electrical_wiring:'',cigarette:'',shutdown_fire:'',combustibles:'',note:''})),status:'draft',updated_at:null,manager_name:'',manager_disposition:'',manager_signature:''};}
function escFire(s){return esc(String(s??''));}
function renderList(){const f=filters();$('#content').innerHTML=`${window.fireFormTabs?.(1)||''}<p class="fire-intro">${tr('fireDailyHelp')}</p><div class="filter-row">${f}<label>${tr('fireMonth')}<input id="fireMonthFilter" type="month" class="select" value="${listMonth}"></label><button class="btn primary" id="fireNew">${tr('fireNew')}</button></div>${table(['fireMonth','department','fireArea','fireImplementer','status','actions'],records.filter(r=>r.inspection_month?.slice(0,7)===listMonth&&(!listDepartment||r.department_id===listDepartment)).map(r=>`<tr><td>${r.inspection_month.slice(0,7)}</td><td>${escFire(localDept(departments.find(d=>d.id===r.department_id)))}</td><td>${escFire(r.responsible_area)}</td><td>${escFire(r.implementer_name)}</td><td>${statusLabel(r.status)}</td><td><button class="btn secondary" data-fire-open="${r.id}">${tr(r.status==='draft'?'fireModify':r.status==='submitted'&&['admin','supervisor'].includes(profile?.role)?'fireReview':'fireOpen')}</button></td></tr>`).join(''))}`;
 window.bindFireFormTabs?.();$('#fireMonthFilter').onchange=e=>{listMonth=e.target.value||monthNow();renderList();};$('#fireListDept').onchange=e=>{listDepartment=e.target.value;renderList();};$('#fireNew').onclick=()=>{current=fresh(listMonth,departments.find(d=>d.id===profile?.department_id)?.id||departments[0]?.id);renderEditor();};
 document.querySelectorAll('[data-fire-open]').forEach(b=>b.onclick=()=>{current=structuredClone(records.find(r=>r.id===b.dataset.fireOpen));renderEditor();});
}
function filters(){const options=departments.map(d=>`<option value="${d.id}" ${d.id===listDepartment?'selected':''}>${escFire(localDept(d))}</option>`).join('');return `<label>${txt('department')}<select id="fireListDept" class="select"><option value="">${txt('all')}</option>${options}</select></label>`;}
const checkFields={fireUse:'fire_use',fireWiring:'electrical_wiring',fireCigarette:'cigarette',fireShutdown:'shutdown_fire',fireCombustibles:'combustibles'};
function restyleEditor(r,locked,reviewer){
 const form=$('#content .fire-form'),fields=form.querySelector('.fire-fields'),grid=form.querySelector('.fire-grid');
 const aliases={'實施項目':'dailyGroup','用火設備':'fireUse','電器設備':'electrical','煙蒂處理':'cigarettes','下班時火源管理':'shutdown','其它（共有設備／設施之可燃物管理）':'combustibles','使用情形':'useCondition','配線':'wiring','煙蒂處理情形':'buttCondition','下班確認情形':'endConfirmation','可燃物管理情形':'combustibleCondition','防火管理人處置情形暨簽章':'managerSection','處置情形':'disposition','簽章':'signature','簽章／簽名':'signature','防火管理人姓名':'managerName','檢查年月':'month','部門':'department','負責區域':'area','實施人員':'implementer','日期':'day','附記':'notes'};
 const mark=(zh,vi)=>{const key=aliases[zh];return key?window.fireI18n.html(key):'<span class="fire-main-translation">'+escFire(zh)+'</span><span class="fire-translation">'+escFire(vi)+'</span>';};
 form.classList.add('fire-sheet');
 const heading=document.createElement('header');
 heading.className='fire-document-heading';
 heading.innerHTML='<span class="fire-appendix">'+window.fireI18n.html('appendix')+' 1</span><div class="fire-document-title"><strong>'+window.fireI18n.html('dailyTitle')+'</strong></div>';
 fields.insertAdjacentElement('beforebegin',heading);
 const meta={fireImplementer:['實施人員','Nhân viên thực hiện'],fireArea:['負責區域','Khu vực phụ trách'],fireMonth:['檢查年月','Tháng kiểm tra'],fireDept:['部門','Bộ phận']};
 for(const id of ['fireImplementer','fireArea','fireMonth','fireDept']){
  const control=form.querySelector('#'+id),label=control.closest('label'),names=meta[id];
  while(label.firstChild&&label.firstChild!==control)label.removeChild(label.firstChild);
  label.insertAdjacentHTML('afterbegin','<span class="fire-field-name">'+mark(names[0],names[1])+'</span>');
  fields.appendChild(label);
 }
 const groups=[['用火設備','Thiết bị dùng lửa'],['電器設備','Thiết bị điện'],['煙蒂處理','Xử lý đầu lọc thuốc lá'],['下班時火源管理','Quản lý nguồn lửa khi tan ca'],['其它（共有設備／設施之可燃物管理）','Khác (quản lý vật liệu dễ cháy tại thiết bị dùng chung)']];
 const details=[['使用情形','Tình trạng sử dụng'],['配線','Dây dẫn điện'],['煙蒂處理情形','Tình trạng xử lý'],['下班確認情形','Xác nhận khi tan ca'],['可燃物管理情形','Quản lý vật liệu dễ cháy']];
 grid.querySelector('thead').innerHTML='<tr class="fire-superhead"><th rowspan="3" class="fire-day-col">'+mark('日期','Ngày')+'</th><th colspan="5">'+mark('實施項目','Hạng mục thực hiện')+'</th><th rowspan="3" class="fire-note-col">'+mark('附記','Ghi chú bổ sung')+'</th></tr><tr class="fire-grouphead">'+groups.map(x=>'<th>'+mark(x[0],x[1])+'</th>').join('')+'</tr><tr class="fire-detailhead">'+details.map(x=>'<th>'+mark(x[0],x[1])+'</th>').join('')+'</tr>';
 for(const input of grid.querySelectorAll('[data-fire-note]')){
  const note=document.createElement('textarea');note.rows=1;note.value=input.value;note.maxLength=input.maxLength;note.disabled=input.disabled;note.dataset.fireNote=input.dataset.fireNote;note.setAttribute('aria-label',input.dataset.fireNote+'日附記 / Ghi chú');input.replaceWith(note);
 }
 const signoff=document.createElement('section');
 signoff.className='fire-signoff';
 signoff.innerHTML='<div class="fire-signoff-heading">'+mark('防火管理人處置情形暨簽章','Tình hình xử lý và ký xác nhận của người quản lý PCCC')+'</div><div class="fire-signoff-cells"><div class="fire-disposition"><div class="fire-cell-title">'+mark('處置情形','Tình trạng xử lý')+'</div><div class="fire-cell-value"></div></div><div class="fire-signature"><div class="fire-cell-title">'+mark('簽章','Ký tên đóng dấu')+'</div><div class="fire-cell-value"></div></div></div>';
 grid.insertAdjacentElement('afterend',signoff);
 const disposition=signoff.querySelector('.fire-disposition .fire-cell-value'),signature=signoff.querySelector('.fire-signature .fire-cell-value');
 const review=form.querySelector('.fire-review');
 if(review&&r.status==='submitted'&&reviewer){
  const move=(id,target,zh,vi)=>{const input=review.querySelector('#'+id),label=input.closest('label');label.replaceChildren(document.createTextNode(zh),Object.assign(document.createElement('small'),{className:'fire-vi',textContent:vi}),input);target.appendChild(label);};
  move('fireDisposition',disposition,'處置情形','Tình trạng xử lý');
  move('fireManagerName',signature,'防火管理人姓名','Tên người quản lý PCCC');
  move('fireSignature',signature,'簽章／簽名','Ký tên đóng dấu');
  review.remove();
 }else if(r.status==='confirmed'){
  disposition.textContent=r.manager_disposition||'';
  signature.innerHTML='<div>'+escFire(r.manager_name||'')+'</div><strong>'+escFire(r.manager_signature||'')+'</strong>';
 }
 const oldHeading=form.querySelector('h3');
 if(oldHeading){if(r.status==='confirmed'&&oldHeading.nextElementSibling?.tagName==='P')oldHeading.nextElementSibling.remove();oldHeading.remove();}
 const note=form.querySelector('.fire-note');if(note)note.remove();
 const legend=document.createElement('div');legend.className='fire-legend';
 legend.innerHTML=window.fireI18n.html('legend');
 const notice=document.createElement('div');notice.className='fire-notice';
 notice.innerHTML=window.fireI18n.html('notice');
 signoff.insertAdjacentElement('afterend',legend);legend.insertAdjacentElement('afterend',notice);
}
function renderEditor(){const r=current;if(!r)return renderList();const locked=['submitted','confirmed'].includes(r.status),reviewer=['admin','supervisor'].includes(profile?.role),dayCount=monthDays(r.inspection_month.slice(0,7));
 const selector=(day,key)=>`<select data-fire-day="${day}" data-fire-key="${key}" aria-label="${day} ${tr(key)}" ${locked?'disabled':''}><option value="" ${!r.entries[day-1]?.[checkFields[key]]?'selected':''}>—</option>${['O','V','X'].map(x=>`<option value="${x}" ${r.entries[day-1]?.[checkFields[key]]===x?'selected':''}>${x}</option>`).join('')}</select>`;
 const rows=r.entries.slice(0,dayCount).map(e=>`<tr><td>${e.day}</td><td>${selector(e.day,'fireUse')}</td><td>${selector(e.day,'fireWiring')}</td><td>${selector(e.day,'fireCigarette')}</td><td>${selector(e.day,'fireShutdown')}</td><td>${selector(e.day,'fireCombustibles')}</td><td><input data-fire-note="${e.day}" value="${escFire(e.note)}" maxlength="1000" ${locked?'disabled':''}></td></tr>`).join('');
 $('#content').innerHTML=`${window.fireFormTabs?.(1)||''}<p class="fire-intro">${tr('fireDailyHelp')}</p><section class="fire-form"><div class="filter-row"><button class="btn secondary" id="fireBack">${txt('cancel')}</button><button class="btn secondary" id="firePrint">${window.fireI18n.t('print')}</button>${!locked?`<button class="btn secondary" id="fireQuickComplete">${window.fireI18n.t('quick')}</button>`:''}${statusLabel(r.status)}</div><div class="fire-fields"><label>${tr('fireMonth')}<input id="fireMonth" type="month" class="select" value="${r.inspection_month.slice(0,7)}" ${locked?'disabled':''}></label><label>${tr('department')}<select id="fireDept" class="select" ${locked?'disabled':''}>${departments.map(d=>`<option value="${d.id}" ${d.id===r.department_id?'selected':''}>${escFire(localDept(d))}</option>`).join('')}</select></label><label>${tr('fireArea')}<input id="fireArea" class="select" maxlength="200" value="${escFire(r.responsible_area)}" ${locked?'disabled':''}></label><label>${tr('fireImplementer')}<input id="fireImplementer" class="select" maxlength="100" value="${escFire(r.implementer_name)}" ${locked?'disabled':''}></label></div><p class="fire-note">${tr('fireAbnormal')}</p><div class="table-wrap fire-grid"><table class="matrix"><thead><tr><th>${tr('fireDay')}</th><th>${tr('fireUse')}</th><th>${tr('fireWiring')}</th><th>${tr('fireCigarette')}</th><th>${tr('fireShutdown')}</th><th>${tr('fireCombustibles')}</th><th>${tr('fireNote')}</th></tr></thead><tbody>${rows}</tbody></table></div>${!locked?`<div class="fire-actions"><button class="btn secondary" id="fireDraftSave">${tr('fireSaveDraft')}</button><button class="btn primary" id="fireSubmit">${tr('fireSubmit')}</button></div>`:''}${r.status==='submitted'&&reviewer?`<h3>${tr('fireManagerTitle')}</h3><div class="fire-review"><label>${tr('fireManagerName')}<input id="fireManagerName" class="select" maxlength="100" value="${escFire(r.manager_name)}"></label><label>${tr('fireDisposition')}<textarea id="fireDisposition" class="select" rows="3" maxlength="2000">${escFire(r.manager_disposition)}</textarea></label><label>${tr('fireSignature')}<input id="fireSignature" class="select" maxlength="100" value="${escFire(r.manager_signature)}"></label></div><div class="fire-actions"><button class="btn primary" id="fireConfirm">${tr('fireComplete')}</button><button class="btn danger" id="fireReturn">${tr('fireReturn')}</button></div>`:''}${r.status==='confirmed'?`<h3>${tr('fireManagerTitle')}</h3><p>${escFire(r.manager_name)} · ${escFire(r.manager_disposition)} · ${escFire(r.manager_signature)}</p>`:''}</section>`;
 restyleEditor(r,locked,reviewer);window.bindFireFormTabs?.();
 $('#fireBack').onclick=()=>historyOrigin?window.renderFireApprovalHistory():renderList();$('#firePrint').onclick=()=>window.printFireForm();
 if($('#fireQuickComplete'))$('#fireQuickComplete').onclick=()=>{const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),month=r.inspection_month.slice(0,7),through=month<today.slice(0,7)?r.entries.length:month===today.slice(0,7)?Number(today.slice(8,10)):0;for(const entry of r.entries.slice(0,through))for(const field of Object.values(checkFields))if(!entry[field])entry[field]='O';document.querySelectorAll('[data-fire-day]').forEach(el=>{const entry=r.entries[Number(el.dataset.fireDay)-1];el.value=entry[checkFields[el.dataset.fireKey]]||'';});};
 if(!locked){$('#fireArea').oninput=e=>{r.responsible_area=e.target.value;};$('#fireImplementer').oninput=e=>{r.implementer_name=e.target.value;};$('#fireDept').onchange=e=>{r.department_id=e.target.value;};}
 if(!locked){$('#fireMonth').onchange=()=>{const month=$('#fireMonth').value;if(!month)return;const old=r.entries.reduce((m,x)=>(m[x.day]=x,m),{});r.inspection_month=month+'-01';r.entries=Array.from({length:monthDays(month)},(_,i)=>old[i+1]||({day:i+1,fire_use:'',electrical_wiring:'',cigarette:'',shutdown_fire:'',combustibles:'',note:''}));renderEditor();};
  $('#fireDraftSave').onclick=()=>save('draft');$('#fireSubmit').onclick=()=>save('submitted');
  document.querySelectorAll('[data-fire-day]').forEach(el=>el.onchange=()=>{r.entries[Number(el.dataset.fireDay)-1][checkFields[el.dataset.fireKey]]=el.value;});
  document.querySelectorAll('[data-fire-note]').forEach(el=>el.oninput=()=>{r.entries[Number(el.dataset.fireNote)-1].note=el.value;});
 }
 if($('#fireConfirm'))$('#fireConfirm').onclick=()=>review('confirm');if($('#fireReturn'))$('#fireReturn').onclick=()=>review('return');
}
async function save(status){const area=$('#fireArea').value.trim(),implementer=$('#fireImplementer').value.trim();if(!area||!implementer){toast('error',tr('fireRequired'));return;}const month=$('#fireMonth').value;if(!month){toast('error');return;}const next={...current,department_id:$('#fireDept').value,inspection_month:month,entries:current.entries,status,responsible_area:area,implementer_name:implementer};try{const out=await api({action:'fire_daily_save',record:next});current=out.record;records=records.filter(x=>x.id!==current.id).concat(current);toast('saved');renderEditor();}catch(e){toast('error',e.message==='fire_daily_incomplete'?tr('fireAllDays'):'');}}
async function review(decision){const manager=$('#fireManagerName').value.trim(),disposition=$('#fireDisposition').value.trim(),signature=$('#fireSignature').value.trim();if(!manager||!disposition||!signature){toast('error',tr('fireReviewRequired'));return;}try{const out=await api({action:'fire_daily_review',id:current.id,updated_at:current.updated_at,manager_name:manager,manager_disposition:disposition,manager_signature:signature,decision});current=out.record;records=records.filter(x=>x.id!==current.id).concat(current);toast('saved');renderEditor();}catch{toast('error');}}
window.renderFireDaily=async function(){try{historyOrigin=false;if(!listMonth)listMonth=monthNow();await fetchList();renderList();}catch{ $('#content').innerHTML=`<div class="empty-note">${txt('error')}</div>`;}};
window.openFireDailyRecord=async function(id){try{await fetchList();const found=records.find(r=>r.id===id&&r.status==='confirmed');if(!found)throw Error('record_unavailable');current=structuredClone(found);historyOrigin=true;renderEditor();}catch{$('#content').innerHTML=`${window.fireFormTabs?.(4)||''}<div class="empty-note">無法開啟簽核紀錄</div>`;window.bindFireFormTabs?.();}};
})();
